package com.playsphere.payment;
import com.playsphere.common.Ids;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="refund_requests") public class RefundRequest{
 @Id @Column(length=36) private String id;@Column(name="payment_id",nullable=false,length=36) private String paymentId;@Column(name="requested_by_user_id",nullable=false,length=36) private String requestedByUserId;@Column(nullable=false,length=500) private String reason;@Column(name="requested_amount",nullable=false,precision=12,scale=2) private BigDecimal requestedAmount;@Column(nullable=false,length=24) private String status;@Column(name="decision_note",length=500) private String decisionNote;@Column(name="decided_by_user_id",length=36) private String decidedByUserId;@Column(name="created_at",nullable=false) private Instant createdAt;@Column(name="decided_at") private Instant decidedAt;
 protected RefundRequest(){}public RefundRequest(String payment,String user,String reason,BigDecimal amount){id=Ids.uuid();paymentId=payment;requestedByUserId=user;this.reason=reason;requestedAmount=amount;status="REQUESTED";createdAt=Instant.now();}
 public String getId(){return id;}public String getPaymentId(){return paymentId;}public String getRequestedByUserId(){return requestedByUserId;}public String getReason(){return reason;}public BigDecimal getRequestedAmount(){return requestedAmount;}public String getStatus(){return status;}public String getDecisionNote(){return decisionNote;}public String getDecidedByUserId(){return decidedByUserId;}public Instant getCreatedAt(){return createdAt;}public Instant getDecidedAt(){return decidedAt;}public void decide(boolean approve,String admin,String note){status=approve?"APPROVED":"REJECTED";decidedByUserId=admin;decisionNote=note;decidedAt=Instant.now();}
}
